mapper.select:
SELECT T.*
  FROM T_EMC_ORDER_TASK T
 WHERE T.ID = #{id}

SELECT T.* FROM (SELECT WM_CONCAT(A.ID) AS IDS, WM_CONCAT(DISTINCT A.TESTNAME) AS TESTNAME, COUNT(DISTINCT A.ORDERID) AS NUM, A.PROJID, A.FOLDERID, A.CONTAINERCATEGORYID, A.CONTAINERCATEGORYCODE, A.CONTAINERCATEGORYNAME, A.CONTAINERGROUP, A.FIXATIVE, A.QCCATEGORYCODE, A.QCNAME, A.ORDERCATEGORY, A.ANALYSISORGID, A.ANALYSISORGNAME, O.ORDERNO, O.ORDERDESC, O.PARENTORDERNO, O.SAMPLEBEGINDATE, F.FOLDERNO, F.SAMPLEORGID, F.SAMPLEORGNAME, S.SAMPLENO, CC.MATERIAL, CC.COLOR, CC.CAPACITY FROM T_EMC_ORDER_TASK A LEFT JOIN T_EMC_ORDER O ON A.ORDERID = O.ID LEFT JOIN T_EMC_SAMPLE S ON O.SAMPLEID = S.ID LEFT JOIN T_EMC_FOLDER F ON A.FOLDERID = F.ID LEFT JOIN T_EMC_CONTAINER_CATEGORY CC ON A.CONTAINERCATEGORYID = CC.ID LEFT JOIN T_EMC_MONITOR_POINT MP ON F.MONITORPOINTID = MP.ID LEFT JOIN T_EMC_QC_CATEGORY QC ON A.QCCATEGORYID = QC.ID WHERE (A.REMARKS IS NULL OR A.REMARKS != '历史数据')
AND A.ANALYSISTYPE = 'analysis'
AND A.STATUS = #{status} AND NOT EXISTS(SELECT 1 FROM T_EMC_ORDER_TASK OT WHERE OT.FOLDERID = A.FOLDERID AND OT.ANALYSISTYPE = 'analysis' AND OT.STATUS = 'draft' )
AND A.STATUS = 'circulate_third' AND A.ANALYSISORGID = #{analysisOrgId}
AND (QC.USECATEGORY IS NULL OR QC.USECATEGORY != 'lab') AND A.CIRCULATIONGROUPNO = #{circulationGroupNo}
AND A.STATUS = #{status} AND A.ANALYSISORGID = #{analysisOrgId}
AND F.TERMINATION != '1' AND A.ANALYSISTYPE = 'analysis' AND (QC.USECATEGORY IS NULL OR QC.USECATEGORY != 'lab') AND A.STATUS NOT IN ('draft', 'circulate_first', 'circulate_second', 'circulate_third', 'preLogged_first') AND A.ANALYSISORGID = #{analysisOrgId}
AND A.STATUS = #{status} AND A.PROJID = #{projId}
AND A.PROJID = #{projId} AND A.STATUS = 'waitAdd'
AND A.FOLDERID = #{folderId} AND A.QCCATEGORYCODE = 'N/A' AND A.ANALYSISTYPE = 'analysis'
AND A.STATUS = #{orderTaskStatus}
AND A.FOLDERID IN (${folderIds})
AND O.SAMPLEID = #{sampleId}
AND A.ORDERID = #{orderId}
GROUP BY A.FOLDERID, A.ORDERID, A.CONTAINERGROUP, A.CONTAINERCATEGORYID, A.CONTAINERCATEGORYCODE, A.CONTAINERCATEGORYNAME, A.FIXATIVE, A.QCNAME ) T
ORDER BY
T.SAMPLEBEGINDATE ASC
